if(!familyReserve)throw new Error("Matriz oficial de ganhos incompleta");
PLAN100.splice(0,PLAN100.length,...PLAN100.filter(function(r){return !String(r["ID Plano"]||"").startsWith("DOS-")&&!([4931,4932].includes(Number(r["ID GeoHub"]))&&r.Intervencao.startsWith("Adquirir, selecionar"))}));
PLAN100.forEach(function(r){if(([2750,273].includes(Number(r["ID GeoHub"])))&&(r.Intervencao.startsWith("Adquirir e instalar")||r.Intervencao.startsWith("Instalar 1 CMB"))){r.Intervencao=familyReserve["Família de intervenção"];}});
