initPlan=function(id){
 original.init(id);
 var panel=document.getElementById(id);
 if(id==="p100"){var oldNotice=panel.querySelector(":scope > .note");if(oldNotice&&oldNotice.textContent.indexOf("Dosagem")!==-1)oldNotice.remove()}
 var area=document.createElement("div");area.innerHTML=extraHtml(id);
 var before=panel.querySelector(".viz-grid");if(before)before.before(area);else panel.appendChild(area);
 option(id,"local",plans[id],"Instalacao");
 option(id,"gain",plans[id],"Tipo de ganho");
 ["local","gain","quick"].forEach(function(k){var el=document.getElementById(id+"_"+k);if(el)el.addEventListener("change",function(){applyPlan(id)})});
 document.getElementById(id+"_reserve").addEventListener("input",function(e){capacityInputChanged(e.target.value)});
 document.getElementById(id+"_metric").addEventListener("change",function(){updateMunicipal(id,states[id].filtered)});
 document.getElementById(id+"_reset").addEventListener("click",function(){selectMapCity(id,"")});
 document.getElementById(id+"_view").addEventListener("click",function(){var m=mapInstances[id];if(m&&m.homeBounds)m.map.fitBounds(m.homeBounds,{padding:[24,24],maxZoom:10})});
 document.getElementById(id+"_expand").addEventListener("click",function(){var m=document.getElementById(id+"_mapsec"),full=m.classList.toggle("orion-map-full");document.getElementById(id+"_expand").textContent=full?"✕ Fechar ampliação":"⛶ Ampliar mapa";document.getElementById(id+"_expand").setAttribute("aria-expanded",String(full));document.body.style.overflow=full?"hidden":"";if(mapInstances[id])setTimeout(function(){mapInstances[id].map.invalidateSize()},90)});
 original.apply(id);if(!mapInstances[id])loadMap(id);
};
applyPlan=function(id){
 var s=states[id];if(!s)return;
 var q=String(document.getElementById(id+"_q").value||"").toLowerCase();
 var tests=[["Polo",id+"_polo"],["Municipio",id+"_muni"],["Sistema",id+"_sist"],["Disciplina",id+"_disc"],["Prioridade",id+"_prio"],["Criticidade",id+"_critf"],["Instalacao",id+"_local"],["Tipo de ganho",id+"_gain"]];
 var quick=document.getElementById(id+"_quick");
 s.filtered=s.all.filter(function(r){
  if(q&&Object.values(r).join(" ").toLowerCase().indexOf(q)===-1)return false;
  if(!tests.every(function(t){var el=document.getElementById(t[1]);return !el||!el.value||String(r[t[0]]||"")===el.value}))return false;
  if(quick&&quick.value){var v=norm(r["Ganho rápido"]);if(quick.value==="sim"&&!v.startsWith("sim"))return false;if(quick.value==="potencial"&&!v.startsWith("potencial"))return false;if(quick.value==="nao"&&(v.startsWith("sim")||v.startsWith("potencial")))return false;}
  return true;
 });
 renderPlan(id);
};
renderPlan=function(id){
 original.render(id);
 var d=states[id].filtered,div=document.getElementById(id+"_cost");
 if(div)div.textContent=moneyOrBlank(d.reduce(function(s,r){return s+Number(r["Custo do horizonte (R$)"]||0)},0));
 var ps=document.getElementById(id);var head=ps?ps.querySelector(".plan-head .kpi:last-child .label"):null;if(head)head.textContent="Custo previsto ORION";
 var oldTable=ps?ps.querySelector(".table-panel th:last-child"):null;if(oldTable)oldTable.textContent="Custo gerencial";
 if(document.getElementById(id+"_orion_stats"))stats(id,d);
};
switchTab=function(id,button){original.switchTab(id,button);if(mapInstances[id])setTimeout(function(){mapInstances[id].map.invalidateSize()},100)};
openDetail=function(id,i){
 original.detail(id,i);
 var r=states[id]&&states[id].all[i];if(!r)return;
 var d=document.getElementById("drawerBody");
 if(d)d.insertAdjacentHTML("beforeend","<div class=\"orion-section\"><h3>Ganhos e comprovação — base ORION</h3><div class=\"orion-small\"><b>Governança:</b> Plano vigente<br><b>Classe:</b> "+esc(r["Classe de benefício"])+"<br><b>Tipo:</b> "+esc(r["Tipo de ganho"])+"<br><b>Ganho esperado:</b> "+esc(r["Ganho esperado"])+"<br><b>Indicador:</b> "+esc(r.Indicador)+"<br><b>Classificação de ganho rápido:</b> "+esc(r["Ganho rápido"])+"<br><b>Equipe executora:</b> "+esc(r["Equipe executora"])+"<br><b>Dependências:</b> "+esc(r["Dependências gerenciais"])+"<br><b>Comprovação:</b> "+esc(r["Realização do benefício"])+"<br><b>Linha de base e meta:</b> ainda não quantificadas<br><b>Execução:</b> não informada na base gerencial.</div></div>");
};
onlyDosage=function(){var e=document.getElementById("evolucoesTecnicas");if(e)e.scrollIntoView({behavior:"smooth"});else switchTab("p100",document.querySelector(".tab[data-tab=p100]"))};
all100=function(){var e=document.getElementById("p100_q");if(e){e.value="";applyPlan("p100")}};
function selectMapCity(id,city){var sel=document.getElementById(id+"_muni");if(!sel)return;sel.value=(sel.value===city?"":city);applyPlan(id);var m=mapInstances[id];if(city&&sel.value&&m){var l=m.layers.get(norm(city));if(l)m.map.fitBounds(l.getBounds(),{padding:[45,45],maxZoom:11})}else if(m&&m.homeBounds)m.map.fitBounds(m.homeBounds,{padding:[24,24],maxZoom:10});}
function updateMunicipal(id,rows){
 var box=document.getElementById(id+"_maplist");if(!box)return;
 var metric=document.getElementById(id+"_metric").value;
 var selected=document.getElementById(id+"_muni").value;
 var banner=document.getElementById(id+"_selected"),reset=document.getElementById(id+"_reset");if(reset)reset.disabled=!selected;
 if(banner){banner.hidden=!selected;banner.innerHTML=selected?"<b>Município selecionado: "+esc(selected)+"</b><span>Filtro ativo neste horizonte</span><button type=\"button\" id=\""+id+"_bannerreset\">✕ Mostrar todos</button>":"";if(selected)document.getElementById(id+"_bannerreset").addEventListener("click",function(){selectMapCity(id,"")})}
 var groups=new Map();var baseRows=selected?plans[id].filter(function(r){return r.Municipio===selected||rows.some(function(x){return x===r})||(!document.getElementById(id+"_polo").value||r.Polo===document.getElementById(id+"_polo").value)}):rows;
 if(selected){baseRows=plans[id].filter(function(r){return ["Polo","Sistema","Disciplina","Prioridade","Criticidade"].every(function(k){var suffix={Polo:"polo",Sistema:"sist",Disciplina:"disc",Prioridade:"prio",Criticidade:"critf"}[k],el=document.getElementById(id+"_"+suffix);return !el||!el.value||r[k]===el.value})&&(!document.getElementById(id+"_local").value||r.Instalacao===document.getElementById(id+"_local").value)&&(!document.getElementById(id+"_gain").value||r["Tipo de ganho"]===document.getElementById(id+"_gain").value)})}
 baseRows.forEach(function(r){var n=r.Municipio,k=norm(n),g=groups.get(k)||{name:n,total:0,critica:0,imediata:0};g.total++;if(r.Criticidade==="Crítica")g.critica++;if(norm(r.Prioridade).indexOf("imediata")>=0)g.imediata++;groups.set(k,g)});
 var ordered=[...groups.values()].sort(function(a,b){return b[metric]-a[metric]||a.name.localeCompare(b.name,"pt-BR")}),max=Math.max(1,...ordered.map(function(x){return x[metric]}));
 box.innerHTML=ordered.map(function(x){return "<button type=\"button\" data-mun=\""+esc(x.name)+"\" aria-pressed=\""+(selected===x.name)+"\">"+esc(x.name)+"<span>"+prettyNum(x[metric])+"</span><div class=\"orion-mapbar\"><i style=\"width:"+Math.round(100*x[metric]/max)+"%\"></i></div></button>"}).join("")||"<p class=\"orion-small\">Nenhum município neste filtro.</p>";
 box.querySelectorAll("button").forEach(function(btn){btn.addEventListener("click",function(){var sel=document.getElementById(id+"_muni");if(sel)selectMapCity(id,btn.dataset.mun)})});
 var instance=mapInstances[id];if(instance&&instance.layers){instance.layers.forEach(function(layer,key){var g=groups.get(key),n=g?g[metric]:0;var color=n===0?"#e7e7e5":n/max>.66?"#c63e3e":n/max>.33?"#c28a18":"#2d865a";layer.setStyle({fillColor:color,fillOpacity:n?.78:.32,color:selected&&norm(selected)===key?"#143e4a":"#fff",weight:selected&&norm(selected)===key?3:1.2});layer.bindTooltip((g?g.name:instance.labels.get(key)||key)+": "+n+" ações neste indicador",{sticky:true})})}
}
function getLeaflet(){if(window.L)return Promise.resolve(window.L);if(leafletLoading)return leafletLoading;leafletLoading=new Promise(function(resolve,reject){var js=document.createElement("script");js.src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js";js.onload=function(){window.L?resolve(window.L):reject(new Error("Leaflet indisponível"))};js.onerror=function(){reject(new Error("Biblioteca externa indisponível"))};document.head.appendChild(js)});return leafletLoading}
async function getCityDirectory(){if(cityDirectory)return cityDirectory;var r=await fetch("https://servicodados.ibge.gov.br/api/v1/localidades/estados/26/municipios");if(!r.ok)throw new Error("IBGE "+r.status);var data=await r.json();cityDirectory=new Map(data.map(function(m){return [norm(m.nome),String(m.id)]}));cityDirectory.set(norm("São Caitano"),cityDirectory.get(norm("São Caetano")));return cityDirectory}
async function geoFor(code){if(geomCache.has(code))return geomCache.get(code);var url="https://servicodados.ibge.gov.br/api/v3/malhas/municipios/"+code+"?formato=application%2Fvnd.geo%2Bjson&qualidade=minima";var r=await fetch(url,{headers:{"Accept":"application/vnd.geo+json"}});if(!r.ok)throw new Error("Malha não disponível");var g=await r.json();geomCache.set(code,g);return g}
async function loadMap(id){
 var status=document.getElementById(id+"_mapstatus");if(!status||mapInstances[id])return;
 try{
  var results=await Promise.all([getLeaflet(),getCityDirectory()]),L=results[0],dir=results[1];
  if(!document.getElementById(id+"_map"))return;
  var map=L.map(id+"_map",{scrollWheelZoom:false}).setView([-8.25,-36.1],8);
  L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:14,attribution:"© OpenStreetMap · Municípios: IBGE"}).addTo(map);
  var instance={map:map,layers:new Map(),labels:new Map()};mapInstances[id]=instance;
  var names=[...new Set(plans[id].map(function(x){return x.Municipio}))],entries=names.map(function(n){return {name:n,code:dir.get(norm(n))}}).filter(function(x){return x.code});
  var good=0;
  for(var start=0;start<entries.length;start+=7){
   var batch=entries.slice(start,start+7),geos=await Promise.allSettled(batch.map(function(e){return geoFor(e.code)}));
   geos.forEach(function(x,i){if(x.status!=="fulfilled")return;var e=batch[i];try{var layer=L.geoJSON(x.value,{style:{color:"#fff",weight:1.2,fillColor:"#e7e7e5",fillOpacity:.4}}).addTo(map);layer.on("click",function(){selectMapCity(id,e.name)});instance.layers.set(norm(e.name),layer);instance.labels.set(norm(e.name),e.name);good++}catch(err){}});
   status.textContent="Carregamento do mapa: "+good+"/"+entries.length+" municípios.";
   updateMunicipal(id,states[id]?states[id].filtered:plans[id]);
  }
  if(good){instance.homeBounds=L.featureGroup([...instance.layers.values()]).getBounds();map.fitBounds(instance.homeBounds,{padding:[24,24],maxZoom:10});status.textContent=good+"/"+entries.length+" malhas municipais carregadas; áreas agregadas por município, sem pontos de ativos."}
  else status.textContent="Mapa geográfico indisponível nesta conexão. A lista de municípios e os filtros continuam funcionando.";
 }catch(err){status.textContent="Mapa geográfico indisponível nesta conexão; a lista territorial permanece funcional."}
}


